class Solution {
    public int maximumBags(int[] capacity,int[] rocks,int additionalRocks){
        int[] deficits=new int[capacity.length];
        for(int i=0;i<capacity.length;i++)deficits[i]=capacity[i]-rocks[i];
        Arrays.sort(deficits);
        int answer=0;
        for(int deficit:deficits){
            if(deficit>additionalRocks)break;
            additionalRocks-=deficit;
            answer++;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumBags(capacity:IntArray,rocks:IntArray,additionalRocksValue:Int):Int{
        val deficits=IntArray(capacity.size){
            capacity[it]-rocks[it]
        };
        deficits.sort();
        var remaining=additionalRocksValue;
        var answer=0;
        for(deficit in deficits){
            if(deficit>remaining)break;
            remaining-=deficit;
            answer++
        };
        return answer
    }
}

